BEGIN READ ONLY; SELECT jsonb_build_object('observed_at',clock_timestamp(),'read_only',current_setting('transaction_read_only'),'requested_names',ARRAY['create_catalog_calculator_with_audit','record_calculator_qa_decision','assign_calculator_reviewer','transition_calculator_with_audit','prepare_catalog_inventory_drafts','publish_calculator_batch_with_audit_v1'],'observed_overloads',coalesce((SELECT jsonb_agg(jsonb_build_object('name',p.proname,'signature',pg_get_function_identity_arguments(p.oid),'owner',pg_get_userbyid(p.proowner),'security_definer',p.prosecdef,'acl',p.proacl::text,'definition_sha256',encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')) ORDER BY p.proname,pg_get_function_identity_arguments(p.oid)) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prokind='f' AND p.proname IN ('create_catalog_calculator_with_audit','record_calculator_qa_decision','assign_calculator_reviewer','transition_calculator_with_audit','prepare_catalog_inventory_drafts','publish_calculator_batch_with_audit_v1')),'[]'::jsonb)) AS evidence; ROLLBACK;
